// Base58 alphabet (Bitcoin variant), matching Python's base58 package.
export const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

// Map from character to its index in the alphabet.
export const ALPHABET_INDEX = new Map(
  Array.from(ALPHABET, (ch, i) => [ch, i])
);

