import { ALPHABET } from './alphabet.mjs';

const BASE = 58n;

// Encode a non-negative integer into its base58 string representation,
// mirroring base58.b58encode_int. Zero encodes to '1'.
export function b58encodeInt(value) {
  let n = BigInt(value);
  if (n < 0n) {
    throw new Error('b58encode_int: value must be non-negative');
  }
  if (n === 0n) {
    return ALPHABET[0];
  }
  let out = '';
  while (n > 0n) {
    const rem = n % BASE;
    n = n / BASE;
    out = ALPHABET[Number(rem)] + out;
  }
  return out;
}

// Render the encoded string the way Python prints a bytes object: b'...'
export function asPythonBytes(str) {
  return "b'" + str + "'";
}

