import { ALPHABET_INDEX } from './alphabet.mjs';

const BASE = 58n;

// Decode a base58 string into an integer, mirroring base58.b58decode_int.
// Returns a BigInt when the value exceeds Number.MAX_SAFE_INTEGER,
// otherwise a Number, so stringification matches Python's int printing.
export function b58decodeInt(str) {
  let num = 0n;
  for (const ch of String(str)) {
    const idx = ALPHABET_INDEX.get(ch);
    if (idx === undefined) {
      throw new Error("Invalid character '" + ch + "'");
    }
    num = num * BASE + BigInt(idx);
  }
  if (num <= BigInt(Number.MAX_SAFE_INTEGER)) {
    return Number(num);
  }
  return num;
}

