// Minimal argparse-style parser supporting: --name value, --name=value,
// required options, and int/str types. Errors mirror argparse's behavior
// of writing to stderr and exiting with code 2.
export function parseArgs(argv, specs) {
  const result = {};
  const errors = [];

  for (let i = 0; i < argv.length; i++) {
    const token = argv[i];
    let name = null;
    let rawValue = null;

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(2, eq);
        rawValue = token.slice(eq + 1);
      } else {
        name = token.slice(2);
        if (i + 1 < argv.length) {
          rawValue = argv[++i];
        } else {
          errors.push('argument --' + name + ': expected one argument');
          continue;
        }
      }
    } else {
      errors.push('unrecognized arguments: ' + token);
      continue;
    }

    const spec = specs[name];
    if (!spec) {
      errors.push('unrecognized arguments: ' + token);
      continue;
    }

    if (spec.type === 'int') {
      const parsed = /^[+-]?\d+$/.test(rawValue) ? BigInt(rawValue) : null;
      if (parsed === null) {
        errors.push("argument --" + name + ": invalid int value: '" + rawValue + "'");
        continue;
      }
      result[name] = parsed;
    } else {
      result[name] = rawValue;
    }
  }

  for (const [name, spec] of Object.entries(specs)) {
    if (spec.required && !(name in result)) {
      errors.push('the following arguments are required: --' + name);
    }
  }

  if (errors.length > 0) {
    for (const err of errors) {
      console.error(err);
    }
    process.exit(2);
  }

  return result;
}

