import { parseArgs } from './cli/argParser.mjs';
import { b58encodeInt, asPythonBytes } from './base58/encode.mjs';
import { b58decodeInt } from './base58/decode.mjs';

const args = parseArgs(process.argv.slice(2), {
  a: { type: 'int', required: true },
  b: { type: 'int', required: true },
  c: { type: 'str', required: true },
});

const encodedInt1 = b58encodeInt(args.a); // 编码第一个整数
const encodedInt2 = b58encodeInt(args.b); // 编码第二个整数
const decodedInt = b58decodeInt(args.c);  // 解码为整数
console.log(asPythonBytes(encodedInt1));
console.log(asPythonBytes(encodedInt2));
console.log(decodedInt);

